interface ButtonProps extends PropsWithChildren {
  onPress: () => void;
  disabled?: boolean;
  loading?: boolean;
  variant?: "primary" | "secondary" | "quiet" | "danger";
  compact?: boolean;
  accessibilityLabel?: string;
  style?: ViewStyle;
}

export function Button({
  children,
  onPress,
  disabled = false,
  loading = false,
  variant = "primary",
  compact = false,
  accessibilityLabel,
  style,
}: ButtonProps) {
  const inactive = disabled || loading;
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel}
      accessibilityState={{ disabled: inactive, busy: loading }}
      disabled={inactive}
      onPress={onPress}
      style={({ pressed }) => [
        styles.base,
        compact ? styles.compact : styles.regular,
        styles[variant],
        pressed && !inactive ? styles[`${variant}Pressed`] : null,
        inactive ? styles.disabled : null,
        style,
      ]}
    >
      {loading ? (
        <ActivityIndicator size="small" color={variant === "primary" ? colors.primaryInk : colors.text} />
      ) : (
        <Text style={[styles.label, variant === "primary" ? styles.primaryLabel : styles.defaultLabel]}>
          {children}
        </Text>
      )}
    </Pressable>
  );
}

