import { keatingDesignContract, type DesignThemeName } from "@keating/design-contract";
import { createContext, createElement, type PropsWithChildren, useContext, useMemo } from "react";
import { useColorScheme, type TextStyle, type ViewStyle } from "react-native";

export type NativeThemeName = DesignThemeName;

export interface NativeTheme {
  readonly name: NativeThemeName;
  readonly colors: {
    readonly background: string;
    readonly backgroundDeep: string;
    readonly surface: string;
    readonly surfaceRaised: string;
    readonly surfacePressed: string;
    readonly text: string;
    readonly textMuted: string;
    readonly textFaint: string;
    readonly primary: string;
    readonly primaryStrong: string;
    readonly primaryInk: string;
    readonly border: string;
    readonly borderStrong: string;
    readonly error: string;
    readonly errorSurface: string;
    readonly warning: string;
    readonly success: string;
    readonly info: string;
    readonly userBubble: string;
    readonly overlay: string;
  };
  readonly statusBarStyle: "light" | "dark";
}

/** Native projection of the browser-, terminal-, and platform-neutral contract. */
export function projectNativeTheme(name: NativeThemeName): NativeTheme {
  const colors = keatingDesignContract.themes[name].colors;
  return {
    name,
    colors: {
      background: colors.surface,
      backgroundDeep: colors.surfaceMuted,
      surface: colors.surfaceRaised,
      surfaceRaised: colors.surfaceMuted,
      surfacePressed: colors.surfaceMuted,
      text: colors.text,
      textMuted: colors.mutedText,
      textFaint: colors.mutedText,
      primary: colors.accent,
      primaryStrong: colors.accentText,
      primaryInk: colors.onAccent,
      border: colors.border,
      borderStrong: colors.border,
      error: colors.danger,
      errorSurface: colors.surfaceMuted,
      warning: colors.warning,
      success: colors.success,
      info: colors.info,
      userBubble: colors.surfaceMuted,
      overlay: name === "dark" ? "rgba(0, 0, 0, 0.72)" : "rgba(28, 33, 27, 0.28)",
    },
    statusBarStyle: name === "dark" ? "light" : "dark",
  };
}

export const spacing = {
  ...keatingDesignContract.native.spacingDp,
  xxl: keatingDesignContract.native.spacingDp.xl + keatingDesignContract.native.spacingDp.sm,
} as const;
export const radii = {
  sm: keatingDesignContract.native.radiiDp.control,
  md: keatingDesignContract.native.radiiDp.panel,
  lg: keatingDesignContract.native.radiiDp.panel,
  pill: keatingDesignContract.native.radiiDp.pill,
} as const;

export const type = {
  title: { fontSize: 24, lineHeight: 30, fontWeight: "700" } satisfies TextStyle,
  heading: { fontSize: 18, lineHeight: 24, fontWeight: "700" } satisfies TextStyle,
  body: { fontSize: 16, lineHeight: 24 } satisfies TextStyle,
  label: { fontSize: 14, lineHeight: 20, fontWeight: "600" } satisfies TextStyle,
  caption: { fontSize: 12, lineHeight: 17 } satisfies TextStyle,
  mono: { fontFamily: "SpaceMono" } satisfies TextStyle,
} as const;

const ThemeContext = createContext<NativeTheme | null>(null);

export function KeatingThemeProvider({ children }: PropsWithChildren) {
  const systemTheme = useColorScheme();
  const theme = useMemo(() => projectNativeTheme(systemTheme === "light" ? "light" : "dark"), [systemTheme]);
  return createElement(ThemeContext.Provider, { value: theme }, children);
}

export function useKeatingTheme(): NativeTheme {
  const theme = useContext(ThemeContext);
  if (!theme) throw new Error("useKeatingTheme must be used within KeatingThemeProvider.");
  return theme;
}

/** Dark fallback retained only for the isolated repository smoke screen. */
export const colors = projectNativeTheme("dark").colors;
export const hairline: ViewStyle = { borderColor: colors.border, borderWidth: 1 };
