}
import { Fragment, type ReactNode, useState } from "react";
import { Linking, ScrollView, StyleSheet, Text, View } from "react-native";
import { radii, spacing, type, useKeatingTheme } from "@/constants/theme";

type Block = { type: "text"; value: string } | { type: "code"; value: string; language: string };

function markdownBlocks(content: string): Block[] {
  const blocks: Block[] = [];
  const expression = /```([^\n`]*)\n?([\s\S]*?)```/g;
  let cursor = 0;
  for (const match of content.matchAll(expression)) {
    const index = match.index ?? 0;
    if (index > cursor) blocks.push({ type: "text", value: content.slice(cursor, index) });
    blocks.push({ type: "code", language: match[1].trim(), value: match[2].trimEnd() });
    cursor = index + match[0].length;
  }
  if (cursor < content.length) blocks.push({ type: "text", value: content.slice(cursor) });
  return blocks.length > 0 ? blocks : [{ type: "text", value: content }];
}

type MarkdownStyles = ReturnType<typeof createStyles>;

function Spoiler({ children, styles }: { children: string; styles: MarkdownStyles }) {
  const [revealed, setRevealed] = useState(false);
  return (
    <Text
      accessibilityRole="button"
      accessibilityLabel={revealed ? "Hide answer" : "Reveal answer"}
      accessibilityState={{ expanded: revealed }}
      onPress={() => setRevealed((current) => !current)}
      style={revealed ? styles.spoilerRevealed : styles.spoilerHidden}
    >
      {revealed ? children : "Tap to reveal"}
    </Text>
  );
}

function inlineNodes(value: string, styles: MarkdownStyles): ReactNode[] {
  const nodes: ReactNode[] = [];
  const expression = /(\|\|[^|]+\|\||\*\*[^*]+\*\*|`[^`]+`|\[[^\]]+\]\([^)]+\))/g;
  let cursor = 0;
  let key = 0;
  for (const match of value.matchAll(expression)) {
    const index = match.index ?? 0;
    if (index > cursor) nodes.push(value.slice(cursor, index));
    const token = match[0];
    if (token.startsWith("||")) {
      nodes.push(<Spoiler key={key++} styles={styles}>{token.slice(2, -2)}</Spoiler>);
    } else if (token.startsWith("**")) {
      nodes.push(<Text key={key++} style={styles.bold}>{token.slice(2, -2)}</Text>);
    } else if (token.startsWith("`")) {
      nodes.push(<Text key={key++} style={styles.inlineCode}>{token.slice(1, -1)}</Text>);
    } else {
      const link = token.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
      if (link) {
        nodes.push(
          <Text key={key++} style={styles.link} accessibilityRole="link" onPress={() => void Linking.openURL(link[2])}>
            {link[1]}
          </Text>,
        );
      }
    }
    cursor = index + token.length;
  }
  if (cursor < value.length) nodes.push(value.slice(cursor));
  return nodes;
}

function TextBlock({ value, styles }: { value: string; styles: MarkdownStyles }) {
  const lines = value.split("\n");
  return (
    <View style={styles.textBlock}>
      {lines.map((rawLine, index) => {
        const line = rawLine.trimEnd();
        if (!line.trim()) return <View key={index} style={styles.spacer} />;
        const heading = line.match(/^(#{1,3})\s+(.+)$/);
        if (heading) {
          return <Text key={index} style={[styles.paragraph, heading[1].length === 1 ? styles.h1 : styles.h2]}>{inlineNodes(heading[2], styles)}</Text>;
        }
        const bullet = line.match(/^\s*[-*]\s+(.+)$/);
        if (bullet) {
          return (
            <View key={index} style={styles.listRow}>
              <Text style={styles.bullet}>•</Text>
              <Text style={[styles.paragraph, styles.listText]}>{inlineNodes(bullet[1], styles)}</Text>
            </View>
          );
        }
        const numbered = line.match(/^\s*(\d+)\.\s+(.+)$/);
        if (numbered) {
          return (
            <View key={index} style={styles.listRow}>
              <Text style={styles.number}>{numbered[1]}.</Text>
              <Text style={[styles.paragraph, styles.listText]}>{inlineNodes(numbered[2], styles)}</Text>
            </View>
          );
        }
        if (line.startsWith("> ")) {
          return <Text key={index} style={[styles.paragraph, styles.quote]}>{inlineNodes(line.slice(2), styles)}</Text>;
        }
        return <Text key={index} style={styles.paragraph}>{inlineNodes(line, styles)}</Text>;
      })}
    </View>
  );
}

export function MarkdownText({ content }: { content: string }) {
  const styles = createStyles(useKeatingTheme());
  return (
    <View>
      {markdownBlocks(content).map((block, index) => (
        <Fragment key={index}>
          {block.type === "code" ? (
            <View style={styles.codeFrame}>
              {block.language ? <Text style={styles.codeLanguage}>{block.language}</Text> : null}
              <ScrollView horizontal showsHorizontalScrollIndicator contentContainerStyle={styles.codeScroller}>
                <Text selectable style={styles.code}>{block.value}</Text>
              </ScrollView>
            </View>
          ) : <TextBlock value={block.value} styles={styles} />}
        </Fragment>
      ))}
    </View>
  );
}

function createStyles(theme: ReturnType<typeof useKeatingTheme>) {
  const { colors } = theme;
  return StyleSheet.create({
  textBlock: { gap: 2 },
  paragraph: { ...type.body, color: colors.text },
  bold: { fontWeight: "700" },
  inlineCode: { ...type.mono, color: colors.primary, backgroundColor: colors.backgroundDeep },
  spoilerHidden: {
    ...type.label,
    color: colors.primaryInk,
    backgroundColor: colors.primary,
    paddingHorizontal: spacing.sm,
    paddingVertical: spacing.xs,
    borderRadius: radii.sm,
  },
  spoilerRevealed: {
    ...type.body,
    color: colors.text,
    backgroundColor: colors.surfaceRaised,
    paddingHorizontal: spacing.sm,
    paddingVertical: spacing.xs,
    borderRadius: radii.sm,
  },
  link: { color: colors.primary, textDecorationLine: "underline" },
  h1: { ...type.heading, marginTop: spacing.md, marginBottom: spacing.xs },
  h2: { ...type.label, fontSize: 16, marginTop: spacing.md, marginBottom: spacing.xs },
  spacer: { height: spacing.sm },
  listRow: { flexDirection: "row", alignItems: "flex-start", gap: spacing.sm, paddingLeft: spacing.xs },
  bullet: { ...type.body, color: colors.primary, width: 12 },
  number: { ...type.body, ...type.mono, color: colors.primary, minWidth: 24 },
  listText: { flex: 1 },
  quote: {
    color: colors.textMuted,
    paddingHorizontal: spacing.md,
    paddingVertical: spacing.sm,
    backgroundColor: colors.surfaceRaised,
    borderRadius: radii.sm,
  },
  codeFrame: {
    marginVertical: spacing.md,
    overflow: "hidden",
    borderRadius: radii.md,
    backgroundColor: colors.backgroundDeep,
    borderWidth: 1,
    borderColor: colors.border,
  },
  codeLanguage: {
    ...type.caption,
    ...type.mono,
    color: colors.textMuted,
    paddingHorizontal: spacing.md,
    paddingTop: spacing.sm,
  },
  codeScroller: { padding: spacing.md },
  code: { ...type.mono, fontSize: 13, lineHeight: 20, color: colors.text, minWidth: "100%" },
  });
}
import { useState } from "react";
import { Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import { Button } from "@/components/Buttons";
import { radii, spacing, type, useKeatingTheme } from "@/constants/theme";
import type { QuestionField, QuestionForm } from "@/lib/interactive-tags";
import { buildQuestionReport } from "@/lib/quiz-grading";
import { readCardState, writeCardState } from "@/state/card-state";

interface QuestionCardState {
  /** One answer string per field; multi-select answers are comma-joined. */
  answers: string[];
  submitted: boolean;
}

export function QuestionCard({
  form,
  cardKey,
  onSubmit,
}: {
  form: QuestionForm;
  cardKey: string;
  onSubmit: (report: string) => void;
}) {
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const [state, setState] = useState<QuestionCardState>(
    () => readCardState<QuestionCardState>(cardKey) ?? { answers: form.questions.map(() => ""), submitted: false },
  );

  const persist = (next: QuestionCardState) => {
    writeCardState(cardKey, next);
    setState(next);
  };

  const setAnswer = (index: number, value: string) => {
    if (state.submitted) return;
    persist({ ...state, answers: state.answers.map((answer, i) => (i === index ? value : answer)) });
  };

  const answered = state.answers.filter((answer) => answer.trim()).length;

  const submit = () => {
    persist({ ...state, submitted: true });
    onSubmit(buildQuestionReport(form.questions, state.answers, form.topic));
  };

  return (
    <View style={styles.card}>
      {form.intro ? <Text style={styles.intro}>{form.intro}</Text> : null}
      {form.questions.map((field, index) => (
        <QuestionFieldRow
          key={`${field.question}-${index}`}
          field={field}
          answer={state.answers[index] ?? ""}
          submitted={state.submitted}
          onChange={(value) => setAnswer(index, value)}
        />
      ))}
      {state.submitted ? (
        <Text style={styles.sent}>Answers sent to Keating.</Text>
      ) : (
        <Button onPress={submit} disabled={answered === 0} compact>
          Send answers
        </Button>
      )}
    </View>
  );
}

function QuestionFieldRow({
  field,
  answer,
  submitted,
  onChange,
}: {
  field: QuestionField;
  answer: string;
  submitted: boolean;
  onChange: (value: string) => void;
}) {
  const theme = useKeatingTheme();
  const { colors } = theme;
  const styles = createStyles(theme);
  // Multi-select answers are stored comma-joined so every field keeps one
  // string, which is also the shape the report needs.
  const selected = field.multiSelect ? answer.split(",").map((value) => value.trim()).filter(Boolean) : [answer.trim()];

  const toggle = (choice: string) => {
    if (!field.multiSelect) {
      onChange(answer.trim() === choice ? "" : choice);
      return;
    }
    const next = selected.includes(choice) ? selected.filter((value) => value !== choice) : [...selected, choice];
    onChange(next.join(", "));
  };

  return (
    <View style={styles.field}>
      {field.header ? <Text style={styles.header}>{field.header.toUpperCase()}</Text> : null}
      <Text style={styles.question}>{field.question}</Text>
      {field.hint ? <Text style={styles.hint}>{field.hint}</Text> : null}

      {field.choices ? (
        <View style={styles.choices}>
          {field.choices.map((choice) => {
            const active = selected.includes(choice);
            return (
              <Pressable
                key={choice}
                accessibilityRole={field.multiSelect ? "checkbox" : "radio"}
                accessibilityState={{ selected: active, disabled: submitted }}
                disabled={submitted}
                onPress={() => toggle(choice)}
                style={({ pressed }) => [
                  styles.choice,
                  active && styles.choiceActive,
                  pressed && !submitted && styles.choicePressed,
                ]}
              >
                <Text style={[styles.choiceText, active && styles.choiceTextActive]}>{choice}</Text>
              </Pressable>
            );
          })}
        </View>
      ) : null}

      {/* One answer slot per field, so a typed answer replaces a tapped choice
          rather than competing with it. Multi-select keeps its comma-joined
          value out of the input entirely. */}
      {!field.choices || (field.allowText && !field.multiSelect) ? (
        <TextInput
          style={styles.input}
          value={answer}
          editable={!submitted}
          multiline
          placeholder={field.blanks ? "Fill each blank, separated by |" : "Type your answer"}
          placeholderTextColor={colors.textFaint}
          onChangeText={onChange}
        />
      ) : null}
    </View>
  );
}

function createStyles(theme: ReturnType<typeof useKeatingTheme>) {
  const { colors } = theme;
  return StyleSheet.create({
  card: {
    marginVertical: spacing.md,
    gap: spacing.lg,
    paddingLeft: spacing.lg,
    borderLeftWidth: 2,
    borderLeftColor: colors.primaryStrong,
  },
  intro: { ...type.body, color: colors.textMuted },
  field: { gap: spacing.sm },
  header: { ...type.caption, ...type.mono, color: colors.primary, letterSpacing: 1 },
  question: { ...type.body, color: colors.text },
  hint: { ...type.caption, color: colors.textMuted },
  choices: { gap: spacing.sm },
  choice: {
    minHeight: 44,
    justifyContent: "center",
    paddingHorizontal: spacing.md,
    borderRadius: radii.md,
    borderWidth: 1,
    borderColor: colors.border,
  },
  choicePressed: { backgroundColor: colors.surfacePressed },
  choiceActive: { borderColor: colors.primaryStrong, backgroundColor: colors.surfaceRaised },
  choiceText: { ...type.body, color: colors.textMuted },
  choiceTextActive: { color: colors.text },
  input: {
    ...type.body,
    minHeight: 60,
    color: colors.text,
    textAlignVertical: "top",
    padding: spacing.md,
    borderRadius: radii.md,
    borderWidth: 1,
    borderColor: colors.border,
    backgroundColor: colors.backgroundDeep,
  },
  sent: { ...type.caption, color: colors.textMuted },
  });
}
import { useMemo, useState } from "react";
import { Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import { Button } from "@/components/Buttons";
import { MarkdownText } from "@/components/MarkdownText";
import { radii, spacing, type, useKeatingTheme } from "@/constants/theme";
import type { Quiz, QuizQuestion } from "@/lib/interactive-tags";
import { buildQuizReport, isCorrect, isOpenEnded, scoreQuiz } from "@/lib/quiz-grading";
import { readCardState, writeCardState } from "@/state/card-state";

interface QuizCardState {
  answers: Record<string, string>;
  submitted: boolean;
}

export function QuizCard({
  quiz,
  cardKey,
  onSubmit,
}: {
  quiz: Quiz;
  cardKey: string;
  /** Reports the finished quiz back to the teacher as a new learner turn. */
  onSubmit: (report: string) => void;
}) {
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const [state, setState] = useState<QuizCardState>(
    () => readCardState<QuizCardState>(cardKey) ?? { answers: {}, submitted: false },
  );

  const persist = (next: QuizCardState) => {
    writeCardState(cardKey, next);
    setState(next);
  };

  const setAnswer = (id: string, value: string) => {
    if (state.submitted) return;
    persist({ ...state, answers: { ...state.answers, [id]: value } });
  };

  const score = useMemo(
    () => (state.submitted ? scoreQuiz(quiz.questions, state.answers) : null),
    [quiz.questions, state.answers, state.submitted],
  );
  const answered = quiz.questions.filter((question) => (state.answers[question.id] ?? "").trim()).length;

  const submit = () => {
    persist({ ...state, submitted: true });
    onSubmit(buildQuizReport(quiz.topic, quiz.questions, state.answers));
  };

  return (
    <View style={styles.card}>
      <View style={styles.header}>
        <Text style={styles.kicker}>RETRIEVAL PRACTICE</Text>
        <Text style={styles.title}>{quiz.topic}</Text>
      </View>

      {quiz.questions.map((question, index) => (
        <QuizQuestionRow
          key={question.id}
          index={index}
          question={question}
          answer={state.answers[question.id] ?? ""}
          submitted={state.submitted}
          onChange={(value) => setAnswer(question.id, value)}
        />
      ))}

      {score ? (
        <View style={styles.scoreBox}>
          <Text style={styles.scoreValue}>
            {score.correct}/{score.total} correct · {score.percent}%
          </Text>
          <Text style={styles.scoreNote}>
            {score.hasOpenEnded
              ? "Written answers are scored loosely here — Keating gives the real verdict below."
              : "Answers sent to Keating for review."}
          </Text>
        </View>
      ) : (
        <Button onPress={submit} disabled={answered === 0}>
          {answered === quiz.questions.length ? "Submit quiz" : `Submit (${answered}/${quiz.questions.length} answered)`}
        </Button>
      )}
    </View>
  );
}

function QuizQuestionRow({
  index,
  question,
  answer,
  submitted,
  onChange,
}: {
  index: number;
  question: QuizQuestion;
  answer: string;
  submitted: boolean;
  onChange: (value: string) => void;
}) {
  const theme = useKeatingTheme();
  const { colors } = theme;
  const styles = createStyles(theme);
  const correct = submitted && isCorrect(question, answer);
  const options = question.type === "true_false" ? (question.options ?? ["True", "False"]) : question.options;

  return (
    <View style={styles.question}>
      <View style={styles.questionHead}>
        <Text style={styles.questionNumber}>{index + 1}</Text>
        <Text style={styles.questionText}>{question.question}</Text>
      </View>

      {options ? (
        <View style={styles.options}>
          {options.map((option) => (
            <QuizOption
