const ThemeContext = createContext<NativeTheme | null>(null);

export function KeatingThemeProvider({ children }: PropsWithChildren) {
  const systemTheme = useColorScheme();
  const theme = useMemo(() => projectNativeTheme(systemTheme === "light" ? "light" : "dark"), [systemTheme]);
  return createElement(ThemeContext.Provider, { value: theme }, children);
}

export function useKeatingTheme(): NativeTheme {
  const theme = useContext(ThemeContext);
  if (!theme) throw new Error("useKeatingTheme must be used within KeatingThemeProvider.");
  return theme;
}

